import type { SyncV1BaseUnit } from "@prisma/client";
import { IdentificationHttpError } from "./identification-error";

/** UUID v4 in lowercase, as generated by the phone (E1-D3). */
export const CLIENT_REQUEST_ID = /^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/;
/** Any server-generated UUID (institutional routes). */
export const SERVER_ID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/;
export const PHOTO_CONSENT_VERSION = /^FOTO-[1-9][0-9]{0,2}$/;
export const TEXT_MAX = 120;
export const REASON_MAX = 280;

const UNITS: Record<string, SyncV1BaseUnit> = { L: "ML", KG: "G" };

export interface UpsertInput {
  contractVersion: number;
  local_name: string;
  active_ingredient?: string | null;
  unit: string;
  photo_consent?: { version: string; accepted_at: string } | null;
}

export interface NormalizedRequest {
  localName: string;
  activeIngredient: string | null;
  unit: "L" | "KG";
  baseUnit: SyncV1BaseUnit;
  consent: { version: string; acceptedAt: Date } | null;
}

const invalid = () => new IdentificationHttpError(400, "PAYLOAD_INVALID");

/**
 * Body of `PUT /{request_id}` after the DTO's structural check: trimmed
 * lengths (400 PAYLOAD_INVALID) and the closed unit (422 UNIT_UNSUPPORTED).
 */
export function normalizeRequestInput(input: UpsertInput): NormalizedRequest {
  const localName = input.local_name.trim();
  if (localName.length < 1 || localName.length > TEXT_MAX) throw invalid();
  let activeIngredient: string | null = null;
  if (input.active_ingredient !== undefined && input.active_ingredient !== null) {
    activeIngredient = input.active_ingredient.trim();
    if (activeIngredient.length < 1 || activeIngredient.length > TEXT_MAX) throw invalid();
  }
  let consent: NormalizedRequest["consent"] = null;
  if (input.photo_consent) {
    const acceptedAt = new Date(input.photo_consent.accepted_at);
    if (Number.isNaN(acceptedAt.getTime())) throw invalid();
    consent = { version: input.photo_consent.version, acceptedAt };
  }
  const baseUnit = UNITS[input.unit];
  if (!baseUnit) throw new IdentificationHttpError(422, "UNIT_UNSUPPORTED");
  return { localName, activeIngredient, unit: input.unit as "L" | "KG", baseUnit, consent };
}

/**
 * RF-33: nothing is decided without an explicit confirmation and a reason
 * (or note) of 1–280 characters.
 */
export function requireConfirmation(confirmed: unknown, reason: unknown): string {
  if (confirmed !== true) throw new IdentificationHttpError(422, "CONFIRMATION_REQUIRED");
  const trimmed = typeof reason === "string" ? reason.trim() : "";
  if (!trimmed || trimmed.length > REASON_MAX) throw new IdentificationHttpError(422, "REASON_REQUIRED");
  return trimmed;
}
